@IterationAlgebra.ptree_peutt_monad_laws
     : forall (E MN MF : Type -> Type) (NI : Measure.SemanticMeasure MN),
       @Measure.SemanticMeasureCoreLaws MN NI ->
       forall (FI : Measure.SemanticMeasure MF) (FC : @Measure.SemanticMeasureCoreLaws MF FI),
       @Measure.SemanticMeasureBindLaws MF FI ->
       forall (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       @Omega.SemanticMeasureDiagonalLaws MF FI FO ->
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       @Omega.SemanticOmegaDirectedCofinalityLaws MF FI FO ->
       @Omega.SemanticOmegaSelection MF FI FO ->
       @RelationalClosure.relational_mixed_bind MN MF NI FI MX ->
       @RelationalClosure.relational_zero MF FI FO ->
       @RelationalClosure.relational_lub MF FI FO ->
       @Monad.MonadLawsE (PTreeDefinition.ptree E MN)
         (@IterationAlgebra.ptree_peutt_eq1 E MN MF FI FC MX FO)
         (@PTreeDefinition.Monad_ptree E MN)

@IterationAlgebra.peutt_iter_uniform
     : forall (E MN MF : Type -> Type) (NI : Measure.SemanticMeasure MN),
       @Measure.SemanticMeasureCoreLaws MN NI ->
       forall (FI : Measure.SemanticMeasure MF) (FC : @Measure.SemanticMeasureCoreLaws MF FI),
       @Measure.SemanticMeasureBindLaws MF FI ->
       forall (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       @Omega.SemanticMeasureDiagonalLaws MF FI FO ->
       @Omega.SemanticOmegaFubiniLaws MF FI FO ->
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       @Omega.SemanticOmegaDirectedCofinalityLaws MF FI FO ->
       @Omega.SemanticOmegaSelection MF FI FO ->
       @RelationalClosure.relational_mixed_bind MN MF NI FI MX ->
       @RelationalClosure.relational_zero MF FI FO ->
       @RelationalClosure.relational_lub MF FI FO ->
       forall (I J A : Type) (f : I -> PTreeDefinition.ptree E MN (I + A))
         (g : J -> PTreeDefinition.ptree E MN (J + A)) (h : I -> J),
       (forall i : I,
        @PEutt.peutt E MN MF FI FC MX FO (J + A) (J + A) (@eq (J + A))
          (@PTreeDefinition.PTree.bind E MN (I + A) (J + A) (f i)
             (fun v : I + A =>
              {|
                PTreeDefinition._observe :=
                  @PTreeDefinition.RetF E MN (J + A) (PTreeDefinition.ptree E MN (J + A))
                    (@IterationLaws.iteration_map I J A h v)
              |})) (g (h i))) ->
       forall i : I,
       @PEutt.peutt E MN MF FI FC MX FO A A (@eq A) (@PTreeDefinition.PTree.iter E MN A I f i)
         (@PTreeDefinition.PTree.iter E MN A J g (h i))

@IterationAlgebra.ptree_peutt_iter_unfold
     : forall (E MN MF : Type -> Type) (NI : Measure.SemanticMeasure MN),
       @Measure.SemanticMeasureCoreLaws MN NI ->
       forall (FI : Measure.SemanticMeasure MF) (FC : @Measure.SemanticMeasureCoreLaws MF FI),
       @Measure.SemanticMeasureBindLaws MF FI ->
       forall (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       @Omega.SemanticMeasureDiagonalLaws MF FI FO ->
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       @Omega.SemanticOmegaDirectedCofinalityLaws MF FI FO ->
       @Omega.SemanticOmegaSelection MF FI FO ->
       @RelationalClosure.relational_mixed_bind MN MF NI FI MX ->
       @RelationalClosure.relational_zero MF FI FO ->
       @RelationalClosure.relational_lub MF FI FO ->
       forall (I A : Type) (step : I -> PTreeDefinition.ptree E MN (I + A)) (i : I),
       @PEutt.peutt E MN MF FI FC MX FO A A (@eq A) (@PTreeDefinition.PTree.iter E MN A I step i)
         (@PTreeDefinition.PTree.bind E MN (I + A) A (step i)
            (fun v : I + A =>
             match v with
             | @inl _ _ j => @PTreeDefinition.PTree.iter E MN A I step j
             | @inr _ _ a =>
                 {|
                   PTreeDefinition._observe :=
                     @PTreeDefinition.RetF E MN A (PTreeDefinition.ptree E MN A) a
                 |}
             end))

@IterationAlgebra.ptree_peutt_iter_tau_step
     : forall (E MN MF : Type -> Type) (NI : Measure.SemanticMeasure MN),
       @Measure.SemanticMeasureCoreLaws MN NI ->
       forall (FI : Measure.SemanticMeasure MF) (FC : @Measure.SemanticMeasureCoreLaws MF FI),
       @Measure.SemanticMeasureBindLaws MF FI ->
       forall (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       @Omega.SemanticMeasureDiagonalLaws MF FI FO ->
       @Omega.SemanticOmegaFubiniLaws MF FI FO ->
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       @Omega.SemanticOmegaDirectedCofinalityLaws MF FI FO ->
       @Omega.SemanticOmegaSelection MF FI FO ->
       @RelationalClosure.relational_mixed_bind MN MF NI FI MX ->
       @RelationalClosure.relational_zero MF FI FO ->
       @RelationalClosure.relational_lub MF FI FO ->
       forall (I A : Type) (step : I -> PTreeDefinition.ptree E MN (I + A)) (i : I),
